// Rating ranges of the playstyle ratings on the other fertility and resource slot settings (min, max, average, median over seeds
// 1..N, per template and size, DLC01 on). The Latium and Albion statistics elsewhere hold Abundant/Abundant only, but Regular and
// Sparse have far fewer mines and fertile coasts: rated against the Abundant range, nearly every such seed would score 0 there.
// Generated with --analyze-playstyle-ranges (20000 seeds); the rows follow Metrics. A map without DLC01 uses the DLC01 row of its template.
internal static class PlaystyleRanges
{
 internal static readonly ScoreMetric[] Metrics=
 [
  ScoreMetric.LatiumRiverSites,ScoreMetric.GoldRiverSites,ScoreMetric.SturgeonRiverSites,ScoreMetric.MarbleSites,ScoreMetric.MineralMines,ScoreMetric.GoldMines,
  ScoreMetric.SilverMines,ScoreMetric.TinMines,ScoreMetric.CopperMines,ScoreMetric.AdvLatiumHarbourMurex,ScoreMetric.AdvLatiumHarbourOysters,
  ScoreMetric.AdvAlbionHarbourSaltwort,ScoreMetric.AdvAlbionHarbourSeaShells,ScoreMetric.AdvAlbionMarshSmallBirds,ScoreMetric.AdvAlbionMarshBeaver,
 ];
 // null: Abundant/Abundant, or a metric that does not depend on the settings (the population statistics apply).
 public static ScoreRange? For(MapProfile profile,FertilitySetting fertility,SlotSetting slots,ScoreMetric metric)
 {
  var index=Array.IndexOf(Metrics,metric);
  if(index<0||!Values.TryGetValue((profile.Template,profile.Size,fertility,slots),out var row))return null;
  var range=row[index];return new(range.Min,range.Max,range.Average,range.Median);
 }
